function fightersScreen(){showPanel(`<div class="panelhead"><div><div class="eyebrow">Choose your legend</div><h2>Fighter roster</h2><div class="sub">${save.unlockedFighters.length} / 20 available · each legend fights with distinct stats and a signature special.</div></div>${backButton()}</div><div class="grid">${roster.map(f=>{let unlocked=save.unlockedFighters.includes(f.id),active=f.id===selectedFighter;return `<button class="card ${active?'selected':''} ${unlocked?'':'locked'}" data-fighter="${f.id}" style="--accent:${f.accent}"><span class="portrait">${f.emoji}</span><strong>${f.name} ${unlocked?'':'🔒'}</strong><small>${f.gender==='F'?'Female':'Male'} · ${f.style}</small><small>Special: ${f.move}</small><small>ATK ${f.stats[1]} · SPD ${f.stats[3]} · DEF ${f.stats[2]}</small><span class="cost">${unlocked?'SELECTED':`UNLOCK · ${f.unlock?.toLocaleString()||'Championship'}`} LC</span></button>`}).join('')}</div><div class="panelactions"><span class="hint">Unlock any legend with earned coins. Four launch fighters are ready to play.</span><button class="btn primary" data-action="fighter-confirm">Choose ${byId(selectedFighter).name}</button></div>`)}
function arenaScreen(){showPanel(`<div class="panelhead"><div><div class="eyebrow">Seven living stages</div><h2>Select arena</h2><div class="sub">Animated environments · ${save.settings.time==='cycle'?'automatic light cycle':save.settings.time+' lighting'}</div></div>${backButton()}</div><div class="grid">${arenas.map((a,i)=>{let ok=save.unlockedArenas.includes(i),active=i===selectedArena;return `<button class="card ${active?'selected':''} ${ok?'':'locked'}" data-arena="${i}" style="--accent:${a.colors[1]}"><span class="portrait">${a.emoji}</span><strong>${a.name} ${ok?'':'🔒'}</strong><small>${a.unlock}</small><small>${['Neon skyline & signage','Lantern-lit wooden hall','Waves, palms & sunset','Steamworks fight pit','Rooftop skyline','Ancient mountain ruins','Roman crowd & banners'][i]}</small><span class="cost">${ok?'AVAILABLE':'LOCKED'}</span></button>`}).join('')}</div><div class="panelactions"><span class="hint">Win matches to open new stages. Locked arenas cannot be entered.</span><button class="btn primary" data-action="arena-confirm">Fight here</button></div>`)}
function shopScreen(){let lists={outfits:roster.flatMap(f=>[{id:`${f.id}-street`,fighter:f.id,name:`${f.name} · Street alt`,desc:'Alternate streetwear palette',price:1000,type:'outfit'},{id:`${f.id}-legend`,fighter:f.id,name:`${f.name} · Legend`,desc:'Championship colorway',price:2500,type:'outfit'}]),accessories:[{id:'red-gloves',name:'Crimson gloves',desc:'A bold classic pair',price:500,type:'accessory',emoji:'🥊'},{id:'gold-boots',name:'Gold high-tops',desc:'Step into the spotlight',price:750,type:'accessory',emoji:'👟'},{id:'star-headband',name:'Star headband',desc:'A bright champion band',price:800,type:'accessory',emoji:'⭐'},{id:'shadow-mask',name:'Shadow mask',desc:'Mystery for the main event',price:900,type:'accessory',emoji:'🥷'}],finishers:roster.map(f=>({id:`${f.id}-finisher`,fighter:f.id,name:`${f.name} · Signature Finish`,desc:f.move+' knockout sequence',price:5000,type:'finisher',emoji:f.emoji}))};let items=lists[shopCategory];showPanel(`<div class="panelhead"><div><div class="eyebrow">Earn it. Wear it. Own the streets.</div><h2>Legends Market</h2><div class="sub">Balance: <b class="coin">${save.coins.toLocaleString()} LC</b> · no duplicates · purchases saved locally</div></div>${backButton()}</div><div class="category">${[['outfits','Outfits'],['accessories','Accessories'],['finishers','Finishers']].map(([id,l])=>`<button class="btn small ${shopCategory===id?'primary':''}" data-category="${id}">${l}</button>`).join('')}</div><div class="grid">${items.map(it=>{let owned=save.owned.includes(it.id),equipped=it.type==='accessory'?save.equipped.accessory===it.id:save.equipped[it.fighter]===it.id;return `<button class="card ${selectedItem===it.id?'selected':''}" data-item="${it.id}" style="--accent:${it.fighter?byId(it.fighter).accent:'#ba8f56'}"><span class="portrait">${it.emoji||'✦'}</span><strong>${it.name}</strong><small>${it.desc}</small><span class="cost">${owned?(equipped?'EQUIPPED · ': 'OWNED · '):`${it.price.toLocaleString()} LC`}</span></button>`}).join('')}</div><div class="panelactions"><span class="hint">Select an item, then purchase or equip it. Cosmetics never affect combat balance.</span><button class="btn" data-action="shop-equip">Equip / Unequip</button><button class="btn primary" data-action="shop-buy">Purchase selected</button></div>`)}
function settingsScreen(){showPanel(`<div class="panelhead"><div><div class="eyebrow">Tune your arcade</div><h2>Settings</h2><div class="sub">Saved on this device.</div></div>${backButton()}</div><div class="settingrow"><label>Difficulty</label><select class="select" id="difficulty"><option value="easy">Easy</option><option value="normal">Normal</option><option value="hard">Hard</option></select></div><div class="settingrow"><label>Arena lighting</label><select class="select" id="time"><option value="cycle">Automatic day / night</option><option value="day">Fixed daytime</option><option value="sunset">Fixed sunset</option><option value="night">Fixed nighttime</option></select></div><div class="settingrow"><label>Touch control size</label><input id="controlSize" type="range" min=".8" max="1.3" step=".05" value="${save.settings.control}"></div><div class="settingrow"><label>Control transparency</label><input id="controlOpacity" type="range" min=".35" max="1" step=".05" value="${save.settings.opacity}"></div><div class="settingrow"><label>Music</label><button class="btn small" data-action="music">${save.settings.music?'ON':'OFF'}</button></div><div class="settingrow"><label>Sound effects</label><button class="btn small" data-action="sfx">${save.settings.sfx?'ON':'OFF'}</button></div><p class="hint">Touch controls are shown in every fight. Landscape layout scales with your screen. Keyboard is also available for desktop testing.</p><div class="panelactions"><button class="btn primary" data-action="settings-save">Save settings</button></div>`);document.getElementById('difficulty').value=save.settings.difficulty;document.getElementById('time').value=save.settings.time}
function startQuick(){championship=false;tournamentIndex=0;selectedArena=save.unlockedArenas.includes(selectedArena)?selectedArena:0;startMatch()}
function beginChampionship(){championship=true;tournamentIndex=0;selectedArena=save.unlockedArenas.includes(5)?5:0;startMatch()}
function unlockArenaProgress(){[3,6,10,15].forEach((n,j)=>{if(save.wins>=n&&!save.unlockedArenas.includes(j+1))save.unlockedArenas.push(j+1)});persist()}
function opponentForTour(){const available=roster.filter(f=>f.id!==selectedFighter);let idx=Math.min(tournamentIndex,available.length-1);if(tournamentIndex>=5){let boss={...byId('titan'),name:'IRON EMPEROR',id:'boss',accent:'#e44737',cloth:'#762e35',trim:'#f5c34d',stats:[100,96,90,68,90],move:'Emperor Breaker'};return boss}return available[(idx*3+4)%available.length]}
function fighterWithCosmetics(f){let o={...f},eid=save.equipped[f.id];if(eid){if(eid.endsWith('-street')){o.cloth=f.gender==='F'?'#47759a':'#397c7b';o.trim='#e5c968'}else if(eid.endsWith('-legend')){o.cloth='#63376f';o.trim='#f0cb69'}}o.accessory=save.equipped.accessory||null;return o}
function makeCombatant(f,x){return {fighter:fighterWithCosmetics(f),x,hp:100,meter:0,pose:'idle',vy:0,stun:0,attack:0,cool:0,hitFlash:0,guard:false,combo:0}}
function startMatch(){document.getElementById('controls').classList.remove('hidden');held.clear();document.querySelectorAll('[data-control]').forEach(el=>el.classList.remove('active'));let player=byId(selectedFighter);if(!player||!save.unlockedFighters.includes(player.id)){toast('Choose an unlocked fighter first');fightersScreen();return}let choices=roster.filter(f=>f.id!==player.id&&save.unlockedFighters.includes(f.id));let enemy=championship?opponentForTour():choices[Math.floor(Math.random()*choices.length)]||byId('bruno');let diff=save.settings.difficulty;activeMatch={arena:selectedArena,player:makeCombatant(player,W*.34),enemy:makeCombatant(enemy,W*.66),difficulty:diff,keys:{},aiAction:0,aiThink:0,aiGuard:0,perfect:true,roundsLost:0};round=1;pWins=0;eWins=0;elapsed=60;matchEnded=false;rewardsPaid=false;mode='fight';document.getElementById('mainUI').classList.add('hidden');document.getElementById('shade').classList.add('hidden');document.getElementById('hud').classList.remove('hidden');document.getElementById('matchresult').classList.add('hidden');document.getElementById('arenaCaption').textContent=arenas[selectedArena].name.toUpperCase();setText('pname',player.name);setText('ename',enemy.name);updateHUD();applyControlSettings();announce(championship?`CHAMPIONSHIP · ${tournamentIndex+1}`:'ROUND 1');lastT=performance.now()}
function setText(id,text){document.getElementById(id).textContent=text}
function updateHUD(){if(!activeMatch)return;let p=activeMatch.player,e=activeMatch.enemy;document.getElementById('php').style.width=Math.max(0,p.hp)+'%';document.getElementById('ehp').style.width=Math.max(0,e.hp)+'%';document.getElementById('pmeter').style.width=p.meter+'%';document.getElementById('emeter').style.width=e.meter+'%';setText('timer',Math.ceil(elapsed));setText('pround',pWins);setText('eround',eWins);setText('roundinfo',`ROUND ${round} · FIRST TO 2`)}
function announce(text){let el=document.getElementById('message');el.textContent=text;el.classList.add('show');clearTimeout(msgTimer);msgTimer=setTimeout(()=>el.classList.remove('show'),1050)}
function toast(text){let n=document.getElementById('notice');n.textContent=text;n.classList.add('show');setTimeout(()=>n.classList.remove('show'),1800)}
function applyControlSettings(){const c=document.getElementById('controls');c.style.setProperty('--control-scale',save.settings.control);c.style.opacity=save.settings.opacity;c.style.transform=`scale(${save.settings.control})`;c.style.transformOrigin='bottom center'}
const held=new Set(),controlMap={a:'left',arrowleft:'left',d:'right',arrowright:'right',w:'up',arrowup:'up',s:'down',arrowdown:'down',j:'punch',k:'kick',l:'block',i:'special',u:'special'};
function setControl(control,on){if(on)held.add(control);else held.delete(control);document.querySelectorAll(`[data-control="${control}"]`).forEach(el=>el.classList.toggle('active',on))}
function attack(fighter,type){if(fighter.cool>0||fighter.stun>0)return;if(type==='special'&&fighter.meter<100){toast('Build your meter with attacks');return}if(type==='special')fighter.meter=0;fighter.attack=type==='special'?32:type==='kick'?24:18;fighter.cool=type==='special'?1.15:type==='kick'?.58:.42;fighter.pose=type;fighter.guard=false;playTone(type==='special'?170:type==='kick'?240:310,.08);let m=activeMatch,enemy=fighter===m.player?m.enemy:m.player;let distance=Math.abs(enemy.x-fighter.x),reach=type==='special'?235:type==='kick'?132:105;if(distance<=reach){let power=fighter.fighter.stats[1],strength=(type==='special'?23:type==='kick'?10:7)*(0.72+power/160);if(enemy.guard){strength*=.2;enemy.meter=Math.min(100,enemy.meter+5)}else{strength*=1-enemy.fighter.stats[2]/260;enemy.stun=type==='special'?.32:.18;enemy.pose='hit';enemy.hitFlash=.14}enemy.hp=Math.max(0,enemy.hp-strength);fighter.meter=Math.min(100,fighter.meter+(type==='special'?0:13));fighter.combo++;fighter.lastHit=performance.now();if(fighter.combo>=3)announce(`${fighter.combo} HIT COMBO!`);if(type==='special')announce(fighter.fighter.move.toUpperCase());playTone(enemy.guard?130:85,.1)}else fighter.combo=0}
function controlPlayer(dt){let p=activeMatch.player,e=activeMatch.enemy,move=(held.has('right')?1:0)-(held.has('left')?1:0),speed=225*(.75+p.fighter.stats[3]/200);p.x=Math.max(W*.08,Math.min(W*.92,p.x+move*speed*dt));if(held.has('up')&&p.vy===0)p.vy=-480;if(held.has('down')&&p.vy===0)p.pose='crouch';else if(held.has('block'))p.guard=true;else if(!p.attack&&!p.stun)p.pose=move?'walk':'idle';if(p.vy<0||p.vy>0){p.vy+=1250*dt;p.y=(p.y||0)+p.vy*dt;if(p.y>=0){p.y=0;p.vy=0}}if(p.vy!==0)p.pose='jump';if(p.guard&&!p.attack)p.pose='block';if(held.has('punch'))attack(p,'punch');else if(held.has('kick'))attack(p,'kick');else if(held.has('special'))attack(p,'special');if(Math.abs(e.x-p.x)<58){p.x-=Math.sign(e.x-p.x)*24}}
function controlAI(dt){let m=activeMatch,e=m.enemy,p=m.player,dist=p.x-e.x,abs=Math.abs(dist),difficulty=m.difficulty,brain=difficulty==='easy'?.55:difficulty==='hard'?1.25:.9,speed=(100+e.fighter.stats[3]*.65)*brain;if(e.stun<=0){if(abs>105)e.x+=Math.sign(dist)*speed*dt;else if(abs<72)e.x-=Math.sign(dist)*speed*.18*dt;e.x=Math.max(W*.08,Math.min(W*.92,e.x));e.guard=abs<140&&p.attack>0&&Math.random()<(.18*brain);if(e.guard)e.pose='block';else if(!e.attack)e.pose=abs>120?'walk':'idle';e.aiThink-=dt;if(e.aiThink<=0){e.aiThink=(difficulty==='hard'?.42:difficulty==='easy'?.95:.65)+Math.random()*.38;if(abs<155){let r=Math.random();if(difficulty==='hard'&&e.meter>=100&&r<.2)attack(e,'special');else if(r<.46)attack(e,'punch');else if(r<.85)attack(e,'kick');else e.guard=true}}}else e.guard=false}
function updateFighter(f,dt){f.cool=Math.max(0,f.cool-dt);f.attack=Math.max(0,f.attack-dt*60);f.stun=Math.max(0,f.stun-dt);f.hitFlash=Math.max(0,f.hitFlash-dt);if(f.attack<=0&&f.stun<=0&&!f.guard&&!['walk','jump','crouch'].includes(f.pose))f.pose='idle';if(f.lastHit&&performance.now()-f.lastHit>800)f.combo=0}
function endRound(){let p=activeMatch.player,e=activeMatch.enemy;if(p.hp===e.hp){p.hp=Math.max(1,p.hp);e.hp=Math.max(1,e.hp)}if(p.hp>=e.hp){pWins++;announce('ROUND YOURS!')}else{eWins++;activeMatch.roundsLost++;activeMatch.perfect=false;announce('ROUND LOST')}if(pWins>=2||eWins>=2){finishMatch(pWins>eWins);return}round++;elapsed=60;p.hp=100;e.hp=100;p.meter=Math.min(100,p.meter+25);e.meter=Math.min(100,e.meter+20);p.x=W*.34;e.x=W*.66;p.attack=e.attack=0;p.stun=e.stun=0;p.cool=e.cool=0;p.guard=e.guard=false;setTimeout(()=>{if(mode==='fight'&&!matchEnded)announce(`ROUND ${round} · FIGHT!`)},800);updateHUD()}
function finishMatch(won){if(matchEnded)return;matchEnded=true;let reward=won?(championship?250:120):35;if(won){save.wins++;if(championship){tournamentIndex++;if(tournamentIndex>=6){save.champion=true;save.boss=true;if(!save.unlockedArenas.includes(5))save.unlockedArenas.push(5);if(!save.unlockedArenas.includes(6))save.unlockedArenas.push(6)}}}save.coins+=reward;unlockArenaProgress();persist();const result=document.getElementById('matchresult');let next=championship&&won&&tournamentIndex<6?`<button class="btn primary" data-action="tour-next">Next challenger</button>`:'';let title=won?'VICTORY!':'DEFEAT';result.innerHTML=`<div class="resultbox"><div class="eyebrow">${championship?'CHAMPIONSHIP':'QUICK FIGHT'} · ${won?'WIN':'LOSS'}</div><h2>${title}</h2><p>${won?'The streets remember your name.':'Train up and come back stronger.'}</p><p class="coin">+${reward} LEGEND COINS</p>${championship&&won?`<p>Championship bout ${Math.min(tournamentIndex,6)} of 6</p>`:''}<div class="panelactions" style="justify-content:center">${next}<button class="btn" data-action="rematch">Rematch</button><button class="btn" data-action="home">Main menu</button></div></div>`;result.classList.remove('hidden');document.getElementById('controls').classList.add('hidden')}
function gameLoop(now){requestAnimationFrame(gameLoop);let dt=Math.min(.04,(now-lastT)/1000||0);lastT=now;anim+=dt*60;if(mode!=='fight'||!activeMatch||matchEnded)return;elapsed-=dt;let p=activeMatch.player,e=activeMatch.enemy;controlPlayer(dt);controlAI(dt);updateFighter(p,dt);updateFighter(e,dt);if(Math.abs(p.x-e.x)<52){let mid=(p.x+e.x)/2;p.x=mid+(p.x<e.x?-26:26);e.x=mid+(e.x>p.x?26:-26)}if(p.hp<=0||e.hp<=0||elapsed<=0){if(elapsed<=0)elapsed=0;endRound()}updateHUD()}
requestAnimationFrame(gameLoop);
function playTone(freq,duration){if(!save.settings.sfx)return;try{const AC=window.AudioContext||window.webkitAudioContext;if(!window.audioCtx)window.audioCtx=new AC();let c=window.audioCtx,o=c.createOscillator(),g=c.createGain();o.type='square';o.frequency.value=freq;g.gain.setValueAtTime(.055,c.currentTime);g.gain.exponentialRampToValueAtTime(.001,c.currentTime+duration);o.connect(g);g.connect(c.destination);o.start();o.stop(c.currentTime+duration)}catch{}}
function shopItems(){return {outfits:roster.flatMap(f=>[{id:`${f.id}-street`,fighter:f.id,name:`${f.name} · Street alt`,price:1000,type:'outfit'},{id:`${f.id}-legend`,fighter:f.id,name:`${f.name} · Legend`,price:2500,type:'outfit'}]),accessories:[{id:'red-gloves',price:500,type:'accessory'},{id:'gold-boots',price:750,type:'accessory'},{id:'star-headband',price:800,type:'accessory'},{id:'shadow-mask',price:900,type:'accessory'}],finishers:roster.map(f=>({id:`${f.id}-finisher`,fighter:f.id,price:5000,type:'finisher'}))}[shopCategory]||[]}
function act(action){switch(action){case'play':startQuick();break;case'championship':if(!save.unlockedFighters.includes(selectedFighter)){selectedFighter='kenji'}beginChampionship();break;case'fighters':fightersScreen();break;case'arenas':arenaScreen();break;case'shop':shopCategory='outfits';selectedItem=null;shopScreen();break;case'settings':settingsScreen();break;case'back':showHome();break;case'fighter-confirm':showHome();toast(`${byId(selectedFighter).name} selected`);break;case'arena-confirm':if(save.unlockedArenas.includes(selectedArena))startQuick();else toast('Win more fights to unlock this arena');break;case'settings-save':save.settings.difficulty=document.getElementById('difficulty').value;save.settings.time=document.getElementById('time').value;save.settings.control=Number(document.getElementById('controlSize').value);save.settings.opacity=Number(document.getElementById('controlOpacity').value);persist();applyControlSettings();toast('Settings saved');showHome();break;case'music':save.settings.music=!save.settings.music;persist();settingsScreen();break;case'sfx':save.settings.sfx=!save.settings.sfx;persist();settingsScreen();break;case'shop-buy':{let it=shopItems().find(x=>x.id===selectedItem);if(!it){toast('Select an item first');break}if(save.owned.includes(it.id)){toast('Already owned');break}if(save.coins<it.price){toast('Not enough Legend Coins');break}save.coins-=it.price;save.owned.push(it.id);persist();shopScreen();toast('Purchase complete');break}case'shop-equip':{if(!selectedItem||!save.owned.includes(selectedItem)){toast('Purchase this item first');break}let it=shopItems().find(x=>x.id===selectedItem);if(it?.type==='accessory'){if(save.equipped.accessory===it.id)delete save.equipped.accessory;else save.equipped.accessory=it.id}else if(it?.fighter&&it.type==='outfit'){if(save.equipped[it.fighter]===it.id)delete save.equipped[it.fighter];else save.equipped[it.fighter]=it.id}else{toast('This collectible has no combat effect yet');break}persist();shopScreen();toast('Cosmetic updated');break}case'rematch':document.getElementById('controls').classList.remove('hidden');startMatch();break;case'tour-next':document.getElementById('controls').classList.remove('hidden');startMatch();break;case'home':showHome();break}}
document.addEventListener('click',e=>{let action=e.target.closest('[data-action]')?.dataset.action;if(action){act(action);return}let f=e.target.closest('[data-fighter]');if(f){let id=f.dataset.fighter,def=byId(id);if(save.unlockedFighters.includes(id)){selectedFighter=id;fightersScreen()}else if(def&&save.coins>=def.unlock){save.coins-=def.unlock;save.unlockedFighters.push(id);selectedFighter=id;persist();fightersScreen();toast(`${def.name} unlocked!`)}else toast('Not enough Legend Coins');return}let a=e.target.closest('[data-arena]');if(a){let i=Number(a.dataset.arena);if(save.unlockedArenas.includes(i)){selectedArena=i;arenaScreen()}else toast('This arena is still locked');return}let cat=e.target.closest('[data-category]');if(cat){shopCategory=cat.dataset.category;selectedItem=null;shopScreen();return}let item=e.target.closest('[data-item]');if(item){selectedItem=item.dataset.item;shopScreen()}});
document.addEventListener('pointerdown',e=>{let b=e.target.closest('[data-control]');if(!b||mode!=='fight'||matchEnded)return;b.setPointerCapture?.(e.pointerId);setControl(b.dataset.control,true);if(b.dataset.control==='up')setTimeout(()=>setControl('up',false),150) });document.addEventListener('pointerup',e=>{let b=e.target.closest('[data-control]');if(b)setControl(b.dataset.control,false)});document.addEventListener('pointercancel',e=>{let b=e.target.closest('[data-control]');if(b)setControl(b.dataset.control,false)});
addEventListener('keydown',e=>{let c=controlMap[e.key.toLowerCase()];if(c){e.preventDefault();if(!held.has(c)){setControl(c,true);if(c==='up')setTimeout(()=>setControl('up',false),150)}}if(e.key==='Escape'&&mode==='fight')showHome()});addEventListener('keyup',e=>{let c=controlMap[e.key.toLowerCase()];if(c)setControl(c,false)});
document.getElementById('audioQuick').addEventListener('click',e=>{save.settings.sfx=!save.settings.sfx;save.settings.music=!save.settings.music;e.currentTarget.textContent=save.settings.music?'♫ ON':'♫ OFF';persist()});document.getElementById('mainUI').addEventListener('input',e=>{if(e.target.id==='controlSize'||e.target.id==='controlOpacity'){save.settings.control=Number(document.getElementById('controlSize').value);save.settings.opacity=Number(document.getElementById('controlOpacity').value);applyControlSettings()}});
showHome();document.getElementById('audioQuick').textContent=save.settings.music?'♫ ON':'♫ OFF';
</script></body></html>

