const target=(await(await fetch('http://127.0.0.1:9222/json')).json()).find(x=>x.url.includes('/index.html'));
const ws=new WebSocket(target.webSocketDebuggerUrl);await new Promise((resolve,reject)=>{ws.addEventListener('open',resolve,{once:true});ws.addEventListener('error',reject,{once:true})});
let id=0;const pending=new Map();ws.addEventListener('message',event=>{const message=JSON.parse(event.data);if(message.id&&pending.has(message.id)){pending.get(message.id)(message);pending.delete(message.id)}});
function call(method,params={}){const n=++id;return new Promise(resolve=>{pending.set(n,resolve);ws.send(JSON.stringify({id:n,method,params}))})}
async function ev(expression){const response=await call('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true});if(response.result?.exceptionDetails)throw Error(response.result.exceptionDetails.text);return response.result?.result?.value}
await call('Runtime.enable');await ev(`(()=>{save.settings.difficulty='easy';showHome();startQuick();activeMatch.player.hp=activeMatch.enemy.hp=100;activeMatch.player.cool=activeMatch.enemy.cool=99;held.clear();activeMatch.player.x=51;held.add('left');controlPlayer(1);const leftPlayer=activeMatch.player.x;activeMatch.enemy.x= W-51;activeMatch.player.x= W-50;controlAI(1);const edgeAI=activeMatch.enemy.x;activeMatch.player.x=50;activeMatch.enemy.x=51;const gap=activeMatch.enemy.x-activeMatch.player.x;let p=activeMatch.player,e=activeMatch.enemy;if(Math.abs(gap)<56){let direction=gap===0?(activeMatch.lastFacing||1):Math.sign(gap),mid=(p.x+e.x)/2;p.x=mid-direction*28;e.x=mid+direction*28;let shift=p.x<50?50-p.x:e.x>W-50?W-50-e.x:0;if(shift){p.x+=shift;e.x+=shift}activeMatch.lastFacing=direction}return{width:W,playerLeftClamp:leftPlayer,aiRightClamp:edgeAI,edgeCollision:{player:p.x,enemy:e.x,gap:Math.abs(e.x-p.x)},allInBounds:[leftPlayer>=50,edgeAI<=W-50,p.x>=50,e.x<=W-50]}})()` ).then(result=>console.log('Arena bound checks',result));await ev('showHome()');ws.close();
